import type { Token } from '@pnm/expr';

export type { JsonArray, JsonObject, JsonPrimitive, JsonValue, Token } from '@pnm/expr';

/** Identifier of a net element. Generated by `createId()`, opaque to the model. */
export type Id = string;

export interface Position {
  x: number;
  y: number;
}

export interface Place {
  id: Id;
  name: string;
  position: Position;
  /** Reference into `PetriNet.types` (higher nets, M2). Unused by P/T nets. */
  type?: string;
  /** Optional capacity, an integer >= 1. `undefined` means unbounded. */
  capacity?: number;
  /**
   * Overrides the role computed from the net structure (timed simulation). `quantity` marks a place
   * whose tokens count an amount (kilograms, litres, euros) and belong to no case; it overrides
   * the structural roles `source` and `sink` as well.
   */
  role?: 'case' | 'resource' | 'quantity';
}

/** How long a transition takes to complete once it has started (simulation seconds). */
export type Timing =
  | { kind: 'fixed'; value: number }
  | { kind: 'uniform'; min: number; max: number }
  | { kind: 'exponential'; mean: number };

export interface Transition {
  id: Id;
  name: string;
  position: Position;
  /** Guard expression (higher nets, M2). Unused by P/T nets. */
  guard?: string;
  /** Duration of a firing in the timed simulation. Missing means 0 (atomic firing). */
  timing?: Timing;
  /** Relative weight when the timed simulation resolves a conflict at random. Default 1, > 0. */
  priority?: number;
  /** Arrivals per hour; only meaningful for source transitions (no input arcs). */
  rate?: number;
}

export interface Arc {
  id: Id;
  source: Id;
  target: Id;
  /** Arc weight, an integer >= 1. */
  weight: number;
  /** Arc inscription (higher nets, M2). Unused by P/T nets. */
  inscription?: string;
  /** Optional bend points, in canvas coordinates. */
  points?: Position[];
}

/** Place id -> tokens on that place. Places without an entry are empty. */
export type Marking = Record<Id, Token[]>;

/** Free-text note on the canvas. */
export interface Annotation {
  id: Id;
  text: string;
  position: Position;
}

export type Profile = 'pt-net' | 'json-net';

/**
 * What an indicator counts. `tokens`: the tokens on a place now (a momentary value). `inflow` and
 * `outflow`: the tokens put on / taken from a place in the observation window, over the arcs of
 * the transition `via` only if that is given. `firings`: the firings of a transition in the window.
 * `of` is a place, except for `firings` where it is a transition.
 */
export type IndicatorMeasure =
  | { kind: 'tokens'; of: Id }
  | { kind: 'inflow'; of: Id; via?: Id }
  | { kind: 'outflow'; of: Id; via?: Id }
  | { kind: 'firings'; of: Id };

export type IndicatorMeasureKind = IndicatorMeasure['kind'];

/**
 * A key figure the user defines on a net: `factor` times a measure, divided by a reference. The
 * reference (`per`) is the completed cases of the observation window, the observed hours, or a
 * second measure; without it the value is absolute. If the reference is 0 there is no value.
 */
export interface Indicator {
  /** Unique among the indicators of the net. */
  id: string;
  label: string;
  /** Shown after the value, for example `kg` or `%`. Default none. */
  unit?: string;
  measure: IndicatorMeasure;
  per?: 'case' | 'hour' | IndicatorMeasure;
  /** Default 1; finite. */
  factor?: number;
  /** Decimal places shown, an integer from 0 to 6. Default 1. */
  digits?: number;
}

/** Settings of the timed simulation that are stored with the net. */
export interface SimulationSettings {
  /** Seed of the random number generator. Default 1. */
  seed?: number;
  /** Seconds at the start that are left out of the key figures. Default 0. */
  warmup?: number;
  /** ISO timestamp that simulation time 0 maps to in exports. */
  startTime?: string;
  /** Prefix of generated case ids. Default `C-`. */
  caseIdPrefix?: string;
  /** Key figures defined by the user, computed with the other key figures of a run. */
  indicators?: Indicator[];
}

export interface PetriNet {
  version: '1.0';
  profile: Profile;
  name: string;
  /** JSON Schema objects keyed by type name (higher nets, M2). */
  types: Record<string, unknown>;
  places: Place[];
  transitions: Transition[];
  arcs: Arc[];
  /** Initial marking. */
  marking: Marking;
  annotations?: Annotation[];
  /** Settings of the timed simulation. */
  simulation?: SimulationSettings;
  /**
   * How the net is drawn in the domain view (`@pnm/domain`). The core stores it and passes it
   * through without looking at it; `@pnm/domain` checks it.
   */
  domainView?: unknown;
  /**
   * How the domain view was generated by a language model (model, prompt, rounds). Kept next to the
   * view, not inside it. Passed through like `domainView`; `@pnm/llm` defines and reads it.
   */
  domainViewGeneration?: unknown;
  /**
   * Behavioural properties to check (DECLARE templates and LTLf formulas). The core stores the list
   * and passes it through without looking at it; `@pnm/analysis` defines and checks the schema.
   */
  properties?: unknown;
}

export type Node = Place | Transition;
